void pixels_to_argb1555(ushort *out, uchar *pixels, int count)
{
  int i;
  ushort pixel;

  for (i = 0; i < count; i++) {
    pixel = (uchar)(*pixels++ & 0xf8) << 7;
    pixel |= (uchar)(*pixels++ & 0xf8) << 2;
    pixel |= (uchar)(*pixels++ & 0xf8) >> 3;
    pixel |= (uchar)(*pixels++ & 0x80) << 8;
    *out++ = pixel;
  }
  return;
}

